package fraymus.workspace;

import org.json.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

/** Private immutable sequence data, actual CPU comparisons and gated profile activation. */
public final class TrackingLab implements AutoCloseable {
    private final Path root,stateFile;
    private final LinkedHashMap<String,JSONObject> datasets=new LinkedHashMap<>(),jobs=new LinkedHashMap<>();
    private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"tracking-research");t.setDaemon(true);return t;});
    private final String candidate;
    private String active=TrackingEvaluation.BASELINE,activeHash="",activeJob="";private int generation;
    private JSONArray history=new JSONArray();private JSONObject staging;private final ArrayList<JSONObject> stagedFrames=new ArrayList<>();private long stagedBytes;private volatile boolean closed;
    public TrackingLab(Path project) throws Exception {this(project,Tracking024Evaluation.CANDIDATE);}
    TrackingLab(Path project,String candidate) throws Exception {if(!java.util.List.of(TrackingEvaluation.CANDIDATE,Tracking024Evaluation.CANDIDATE).contains(candidate))throw new IllegalArgumentException("Unknown installed candidate");this.candidate=candidate;root=project.resolve("tracking-lab");stateFile=root.resolve("state.json");if(Files.exists(stateFile)){var s=new JSONObject(Files.readString(stateFile));for(Object x:s.getJSONArray("datasets")){var d=(JSONObject)x;datasets.put(d.getString("id"),d);}for(Object x:s.getJSONArray("jobs")){var j=(JSONObject)x;if(j.getString("status").equals("running"))j.put("status","interrupted").put("reason","Process ended. Start a separate comparison with the same frozen profiles; no partial result was promoted.");jobs.put(j.getString("id"),j);}active=s.optString("activeProfile",TrackingEvaluation.BASELINE);activeHash=s.optString("activeCodeSha256","");activeJob=s.optString("activeJob","");generation=s.optInt("generation");history=s.optJSONArray("history");if(history==null)history=new JSONArray();if(!Tracking024Evaluation.INSTALLED.contains(active)||!activeHash.isEmpty()&&!activeHash.equals(TrackerIdentity.hash(active))){history.put(new JSONObject().put("at",Instant.now().toString()).put("event","code-changed-fallback").put("from",active));active=TrackingEvaluation.BASELINE;activeHash=TrackerIdentity.hash(active);activeJob="";generation++;}persist();}}
    static JSONObject copy(JSONObject o){return new JSONObject(o.toString());}
    private static String canonical(Object value){if(value instanceof JSONObject o){var keys=new ArrayList<>(o.keySet());Collections.sort(keys);var parts=new ArrayList<String>();for(String k:keys)parts.add(JSONObject.quote(k)+":"+canonical(o.get(k)));return "{"+String.join(",",parts)+"}";}if(value instanceof JSONArray a){var parts=new ArrayList<String>();for(Object v:a)parts.add(canonical(v));return "["+String.join(",",parts)+"]";}return JSONObject.valueToString(value);}
    private static String packageHash(JSONObject pack) throws Exception {return PerceptionStore.hash(canonical(pack).getBytes(StandardCharsets.UTF_8));}
    private synchronized void persist() throws Exception {Files.createDirectories(root);while(history.length()>64)history.remove(0);var s=new JSONObject().put("activeProfile",active).put("activeCodeSha256",activeHash).put("activeJob",activeJob).put("generation",generation).put("history",history).put("datasets",new JSONArray(datasets.values())).put("jobs",new JSONArray(jobs.values()));Path tmp=root.resolve("state.tmp");Files.writeString(tmp,s.toString());try{Files.move(tmp,stateFile,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,stateFile,StandardCopyOption.REPLACE_EXISTING);}}
    public synchronized String activeProfile(){return active;}
    public synchronized boolean busy(){return jobs.values().stream().anyMatch(j->j.getString("status").equals("running"));}
    static JSONObject summary(JSONObject j){var out=new JSONObject();for(String k:List.of("id","status","reason","createdAt","completedAt","datasets","completedFrames","totalFrames","gate","autoPromote","activation","profiles","implementations","candidateProfile","protocolEdition"))if(j.has(k))out.put(k,j.get(k));return copy(out);}
    public synchronized JSONObject state() throws Exception {var out=new JSONArray();for(var j:jobs.values())out.put(summary(j));var d=new JSONArray();for(var v:datasets.values())d.put(datasetSummary(v));return new JSONObject().put("activeProfile",active).put("activeCodeSha256",activeHash).put("activeJob",activeJob).put("generation",generation).put("history",history).put("datasets",d).put("jobs",out).put("busy",busy()).put("comparisonCandidate",candidate).put("installedProfiles",new JSONArray(Tracking024Evaluation.INSTALLED)).put("profiles",new JSONArray().put(new JSONObject().put("id",TrackingEvaluation.BASELINE).put("codeSha256",Tracking024Evaluation.codeHash(TrackingEvaluation.BASELINE)).put("implementationSha256",TrackerIdentity.hash(TrackingEvaluation.BASELINE))).put(new JSONObject().put("id",candidate).put("codeSha256",Tracking024Evaluation.codeHash(candidate)).put("implementationSha256",TrackerIdentity.hash(candidate))));}
    static JSONObject datasetSummary(JSONObject d){var out=copy(d);out.put("frameCount",d.getJSONArray("frames").length());out.remove("frames");return out;}
    private JSONObject dataset(String id){UUID.fromString(id);var d=datasets.get(id);if(d==null)throw new IllegalArgumentException("Unknown tracking sequence");return d;}
    public synchronized JSONObject readDataset(String id){return copy(dataset(id));}
    public synchronized JSONObject read(String id){UUID.fromString(id);var j=jobs.get(id);if(j==null)throw new IllegalArgumentException("Unknown tracking comparison");return copy(j);}
    public synchronized JSONObject begin(JSONObject input){SpatialScene.keys(input,"schema","title","sequence","split","objectId","source","license","notes","frameCount");if(input.getString("sequence").length()>80||input.getString("title").length()>120)throw new IllegalArgumentException("Use a short sequence name and title");if(staging!=null)throw new IllegalStateException("Finish or cancel the current sequence import");if(datasets.size()>=12)throw new IllegalStateException("Research sequence history limit reached12");int n=input.getInt("frameCount");if(n<5||n>128||!(input.get("frameCount") instanceof Number v)||v.doubleValue()!=n)throw new IllegalArgumentException("Choose5..128 complete frames");staging=copy(input);staging.put("importId",UUID.randomUUID().toString());stagedFrames.clear();stagedBytes=0;return new JSONObject().put("id",staging.getString("importId")).put("next",0);}
    private void importId(String id){if(staging==null||!staging.getString("importId").equals(id))throw new IllegalStateException("Unknown or expired sequence import");}
    public synchronized JSONObject upload(String id,int ordinal,JSONObject frame) throws Exception {importId(id);if(ordinal<stagedFrames.size()){if(stagedFrames.get(ordinal).similar(frame))return new JSONObject().put("next",stagedFrames.size());throw new IllegalStateException("Sequence frame retry differs");}if(ordinal!=stagedFrames.size()||ordinal>=staging.getInt("frameCount"))throw new IllegalStateException("Sequence upload order changed");if(!(frame.get("sourceFrame") instanceof Number sourceOrdinal)||sourceOrdinal.doubleValue()<0||sourceOrdinal.doubleValue()!=Math.rint(sourceOrdinal.doubleValue()))throw new IllegalArgumentException("Integer source frame ordinal required");for(String key:List.of("imageName","maskName"))if(frame.getString(key).length()>160)throw new IllegalArgumentException("Use source names up to160 characters");byte[] image=TrackingEvaluation.data(frame,"image"),mask=TrackingEvaluation.data(frame,"mask");if(stagedBytes+image.length+mask.length>24_000_000)throw new IllegalArgumentException("Sequence exceeds24 MB");TrackingEvaluation.image(image,false);TrackingEvaluation.image(mask,true);stagedFrames.add(copy(frame));stagedBytes+=image.length+mask.length;return new JSONObject().put("next",stagedFrames.size());}
    public synchronized JSONObject cancelImport(String id){importId(id);staging=null;stagedFrames.clear();stagedBytes=0;return new JSONObject().put("cancelled",true);}
    public synchronized JSONObject commit(String id) throws Exception {importId(id);if(stagedFrames.size()!=staging.getInt("frameCount"))throw new IllegalStateException("Import is incomplete");var pack=copy(staging);pack.remove("importId");pack.remove("frameCount");pack.put("frames",new JSONArray(stagedFrames));var dimensions=TrackingEvaluation.validate(pack);String hash=packageHash(pack);for(var existing:datasets.values())if(existing.getString("contentSha256").equals(hash)){cancelImport(id);return datasetSummary(existing);}
        String datasetId=UUID.randomUUID().toString();Path folder=root.resolve("datasets").resolve(datasetId);Files.createDirectories(folder);var refs=new JSONArray();for(int i=0;i<stagedFrames.size();i++){var frame=stagedFrames.get(i);byte[] image=TrackingEvaluation.data(frame,"image"),mask=TrackingEvaluation.data(frame,"mask");Files.write(folder.resolve(i+".image"),image,StandardOpenOption.CREATE_NEW);Files.write(folder.resolve(i+".mask"),mask,StandardOpenOption.CREATE_NEW);var ref=copy(frame);ref.remove("image");ref.remove("mask");var box=TrackingEvaluation.truth(TrackingEvaluation.image(mask,true),pack.getInt("objectId"));ref.put("reference",box==null?JSONObject.NULL:box.json());refs.put(ref);}pack.put("frames",refs).put("id",datasetId).put("contentSha256",hash).put("width",dimensions.getInt("width")).put("height",dimensions.getInt("height")).put("importedAt",Instant.now().toString());datasets.put(datasetId,pack);cancelImport(id);persist();return datasetSummary(pack);
    }
    public synchronized byte[] image(String id,int ordinal) throws Exception {var d=dataset(id);if(ordinal<0||ordinal>=d.getJSONArray("frames").length())throw new IllegalArgumentException("Unknown source frame");byte[] b=Files.readAllBytes(root.resolve("datasets").resolve(id).resolve(ordinal+".image"));if(!PerceptionStore.hash(b).equals(d.getJSONArray("frames").getJSONObject(ordinal).getString("imageSha256")))throw new IllegalStateException("Research source image integrity changed");return b;}
    JSONObject pack(String id) throws Exception {var d=readDataset(id);for(String key:List.of("id","contentSha256","width","height","importedAt"))d.remove(key);var refs=d.getJSONArray("frames");for(int i=0;i<refs.length();i++){var f=refs.getJSONObject(i);f.remove("reference");f.put("image",Base64.getEncoder().encodeToString(image(id,i)));byte[] b=Files.readAllBytes(root.resolve("datasets").resolve(id).resolve(i+".mask"));if(!PerceptionStore.hash(b).equals(f.getString("maskSha256")))throw new IllegalStateException("Research reference integrity changed");f.put("mask",Base64.getEncoder().encodeToString(b));}String expected=readDataset(id).getString("contentSha256");if(!packageHash(d).equals(expected))throw new IllegalStateException("Research package content integrity changed");TrackingEvaluation.validate(d);return d;}
    public synchronized JSONObject start(JSONArray ids,boolean autoPromote) throws Exception {if(closed||busy())throw new IllegalStateException("One tracking comparison at a time");if(jobs.size()>=16||ids.length()<2||ids.length()>4)throw new IllegalArgumentException("Choose one development and1..3 separate evaluation sequences; comparison limit16");var sequences=new HashSet<String>();var hashes=new HashSet<String>();int development=0,evaluation=0,total=0;var bindings=new JSONArray();for(Object value:ids){String id=value.toString();var d=dataset(id);if(!sequences.add(d.getString("sequence")))throw new IllegalArgumentException("Development and evaluation sequences must differ");if(d.getString("split").equals("development"))development++;else evaluation++;for(Object raw:d.getJSONArray("frames"))if(!hashes.add(((JSONObject)raw).getString("imageSha256")))throw new IllegalArgumentException("Development/evaluation share an exact frame");bindings.put(new JSONObject().put("id",id).put("contentSha256",d.getString("contentSha256")).put("split",d.getString("split")));total+=2*(d.getJSONArray("frames").length()-1);}if(development!=1||evaluation<1)throw new IllegalArgumentException("Exactly one development and at least one evaluation sequence required");var j=new JSONObject().put("id",UUID.randomUUID().toString()).put("status","running").put("reason","Comparing frozen CPU profiles on original sequence pixels").put("createdAt",Instant.now().toString()).put("datasets",bindings).put("autoPromote",autoPromote).put("completedFrames",0).put("totalFrames",total).put("results",new JSONArray()).put("candidateProfile",candidate).put("protocolEdition",candidate.equals(Tracking024Evaluation.CANDIDATE)?"024":"023").put("profiles",new JSONObject().put(TrackingEvaluation.BASELINE,Tracking024Evaluation.codeHash(TrackingEvaluation.BASELINE)).put(candidate,Tracking024Evaluation.codeHash(candidate)));j.put("implementations",new JSONObject().put(TrackingEvaluation.BASELINE,TrackerIdentity.hash(TrackingEvaluation.BASELINE)).put(candidate,TrackerIdentity.hash(candidate))).put("implementationComponents",new JSONObject().put(TrackingEvaluation.BASELINE,TrackerIdentity.components(TrackingEvaluation.BASELINE)).put(candidate,TrackerIdentity.components(candidate)));jobs.put(j.getString("id"),j);persist();worker.submit(()->execute(j.getString("id")));return summary(j);}
    private synchronized boolean cancelled(String id){return closed||!jobs.get(id).getString("status").equals("running");}
    private void execute(String id){try{var j=read(id);String candidate=Tracking024Evaluation.candidate(j);for(Object binding:j.getJSONArray("datasets")){var b=(JSONObject)binding;var source=pack(b.getString("id"));var result=new JSONObject().put("datasetId",b.getString("id")).put("sourceContentSha256",b.getString("contentSha256")).put("split",source.getString("split"));for(String profile:List.of(TrackingEvaluation.BASELINE,candidate)){final int offset; synchronized(this){offset=jobs.get(id).getInt("completedFrames");}result.put(profile,Tracking024Evaluation.evaluate(source,profile,()->cancelled(id),n->{synchronized(this){jobs.get(id).put("completedFrames",offset+n);}}));}synchronized(this){if(cancelled(id))throw new InterruptedException("Comparison cancelled");jobs.get(id).getJSONArray("results").put(result);persist();}}
        var guards=candidate.equals(Tracking024Evaluation.CANDIDATE)?Tracking024Guards.run():TrackingGuards.run(candidate);synchronized(this){if(cancelled(id))throw new InterruptedException("Comparison cancelled");var g=jobs.get(id);g.put("guards",guards).put("gate",gate(g.getJSONArray("results"),guards,candidate)).put("status","completed").put("completedAt",Instant.now().toString());g.put("reason",g.getJSONObject("gate").getBoolean("passed")?"Candidate passed fixed evaluation and negative controls":"Candidate rejected; active tracker remains unchanged");if(g.getBoolean("autoPromote")&&g.getJSONObject("gate").getBoolean("passed"))activate(g);persist();}
    }catch(Exception e){synchronized(this){var g=jobs.get(id);if(g!=null&&!g.getString("status").equals("cancelled"))g.put("status",e instanceof InterruptedException?"cancelled":"interrupted").put("reason",e.getMessage());try{persist();}catch(Exception ignored){}}}}
    static JSONObject gate(JSONArray results,JSONObject guards,String candidate){double before=0,after=0;int n=0,half=0,badBefore=0,badAfter=0;boolean regression=false;var cases=new JSONArray();for(Object value:results){var r=(JSONObject)value;if(!r.getString("split").equals("evaluation"))continue;var a=TrackingEvaluation.metrics(r.getJSONObject(TrackingEvaluation.BASELINE).getJSONArray("frames"));var b=TrackingEvaluation.metrics(r.getJSONObject(candidate).getJSONArray("frames"));int count=a.getInt("scoredFrames");if(count!=b.getInt("scoredFrames"))throw new IllegalStateException("Profile frame counts differ");double delta=b.getDouble("meanIou")-a.getDouble("meanIou");regression|=delta<-.05;before+=a.getDouble("meanIou")*count;after+=b.getDouble("meanIou")*count;n+=count;half+=(int)Math.round(b.getDouble("iouHalfFraction")*count);badBefore+=a.getInt("lowOverlapVisiblePredictions");badAfter+=b.getInt("lowOverlapVisiblePredictions");cases.put(new JSONObject().put("datasetId",r.getString("datasetId")).put("baseline",a).put("candidate",b).put("gain",delta));}double gain=(after-before)/Math.max(1,n),coverage=half/(double)Math.max(1,n);boolean negative=guards.getBoolean("duplicateAmbiguous")&&guards.getBoolean("hiddenHasNoCurrentBox")&&guards.optBoolean("reappearanceRecovered",true);boolean passed=n>0&&gain>=.03&&!regression&&coverage>=.65&&badAfter<=badBefore&&negative;return new JSONObject().put("passed",passed).put("scoredEvaluationFrames",n).put("baselineMeanIou",before/Math.max(1,n)).put("candidateMeanIou",after/Math.max(1,n)).put("pooledMeanIouGain",gain).put("candidateIouHalfFraction",coverage).put("perSequenceRegression",regression).put("lowOverlapVisibleBaseline",badBefore).put("lowOverlapVisibleCandidate",badAfter).put("negativeControlsPassed",negative).put("cases",cases).put("scope","Small declared human-guided box-tracking evaluation; not general category accuracy or official DAVIS mask metrics");}
    private void activate(JSONObject j) throws Exception {String candidate=Tracking024Evaluation.candidate(j);for(Object raw:j.getJSONArray("datasets")){var b=(JSONObject)raw;if(!dataset(b.getString("id")).getString("contentSha256").equals(b.getString("contentSha256")))throw new IllegalStateException("Source binding changed before promotion");pack(b.getString("id"));}if(!j.has("implementations")||!j.getJSONObject("implementations").getString(candidate).equals(TrackerIdentity.hash(candidate)))throw new IllegalStateException("Candidate code changed before promotion");if(!gate(j.getJSONArray("results"),j.getJSONObject("guards"),candidate).getBoolean("passed"))throw new IllegalStateException("Candidate has not passed the fixed gates");if(!active.equals(candidate)){history.put(new JSONObject().put("at",Instant.now().toString()).put("event","promoted").put("from",active).put("to",candidate).put("jobId",j.getString("id")));active=candidate;activeHash=TrackerIdentity.hash(active);activeJob=j.getString("id");generation++;}j.put("activation",new JSONObject().put("profile",active).put("generation",generation));}
    public synchronized JSONObject promote(String id) throws Exception {if(busy())throw new IllegalStateException("Wait for the comparison to settle");var j=jobs.get(id);if(j==null||!j.getString("status").equals("completed"))throw new IllegalArgumentException("Choose a completed comparison");activate(j);persist();return state();}
    public synchronized JSONObject rollback() throws Exception {if(busy())throw new IllegalStateException("Wait or cancel the active comparison");if(!active.equals(TrackingEvaluation.BASELINE)){history.put(new JSONObject().put("at",Instant.now().toString()).put("event","rollback").put("from",active).put("to",TrackingEvaluation.BASELINE).put("jobId",activeJob));active=TrackingEvaluation.BASELINE;activeHash=TrackerIdentity.hash(active);activeJob="";generation++;persist();}return state();}
    public synchronized JSONObject cancel(String id) throws Exception {var j=jobs.get(id);if(j==null)throw new IllegalArgumentException("Unknown comparison");if(j.getString("status").equals("running"))j.put("status","cancelled").put("reason","Stopped; partial results cannot promote a profile");persist();return summary(j);}
    @Override public void close(){closed=true;worker.shutdownNow();}
}
